// CSD_RATIONALE_BEGIN
// Root-cause analysis of attempt 60 (0% accuracy):
//   RenderedEndsWith correctly detected "<<" and activated constrained mode, but the
//   parser treats a single variable token (e.g. "n", "total") as a COMPLETE expression.
//   CloseConstrainedSpan then fires immediately, producing 1-token spans like <<n>>, <<n1>>,
//   <<n2>> instead of one combined expression <<n - n1 - n2>>. The evaluator extracts the
//   LAST span; a 1-token variable name evaluates to the wrong number → 0% accuracy.
//
// Root-cause analysis of best result (40.8%):
//   `next == "<<"` never matched Qwen's space-prefixed " <<"  token, so constrained mode
//   was never entered and generation was fully unconstrained. The model wrote natural
//   multi-token expressions like <<7 * (mult + 1)>>. 40.8% of the time those expressions
//   happened to capture the full answer; the rest failed because the model split one
//   expression across several small spans or left part of it outside any span.
//
// Strategy for 59.2%:
//   1. Always run fully unconstrained (never activate insideConstrained mode), avoiding
//      premature 1-token span closure.
//   2. Use highly targeted guidance that:
//      (a) Explicitly forbids splitting one arithmetic expression across multiple << >> pairs.
//      (b) Requires bare variable names (n not {n}).
//      (c) Requires the FINAL << >> span to be the COMPLETE answer expression.
//      (d) Provides concrete correct/wrong examples that mirror the observed failure patterns.
//   3. At entry, if insideConstrained is already true (open span from prior state),
//      close it within a small budget then reset to unconstrained mode.
//   4. Cost and length invariants are straightforward: the loop increments steps by 1
//      each iteration and appends at most 1 token (EOS breaks without appending).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Initialization: insideConstrainedOut is set from insideConstrained; the precondition
//   guarantees IsValidPrefix(currentConstrained) whenever insideConstrained holds.
//
//   Open-span close block (if any): CloseSpanWithinBudget postcondition guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut) on its outputs.
//   We then unconditionally set insideConstrainedOut := false and currentConstrainedOut := [],
//   making the implication vacuously true.
//
//   While loop: insideConstrainedOut is never modified inside the loop; it remains false
//   throughout, so the implication is vacuously true on every iteration. The invariant
//   is preserved trivially.
//
// Invariant 2 — progress:
//   |generated| <= |generatedPrefix| + steps
//
//   Initialization: generated = generatedPrefix, steps = 0; equality holds.
//
//   Open-span close block: closeBudget <= remaining = maxSteps - steps <= maxSteps.
//   CloseSpanWithinBudget postcondition gives |cg| <= |generated| + closeBudget.
//   After steps := steps + closeBudget, |generated| = |cg| <= |generatedPrefix| + closeBudget
//   = |generatedPrefix| + steps. ✓
//
//   While loop body: each iteration increments steps by 1 and either breaks (EOS, no append)
//   or appends exactly 1 token to generated. So |generated_new| <= |generated_old| + 1
//   = |generated_old| + (steps_new - steps_old) <= |generatedPrefix| + steps_new. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve this math problem step-by-step.\n" +
  "CRITICAL RULE FOR << >> SPANS:\n" +
  "Each << >> pair must contain ONE COMPLETE arithmetic expression — never split a single computation across multiple << >> pairs.\n" +
  "CORRECT: <<total - n1 - n2>>  (complete expression in ONE span)\n" +
  "WRONG:   <<total>> - <<n1>> - <<n2>>  (expression split across spans — NEVER do this)\n" +
  "CORRECT: <<(n + n * mult) * 7>>  (full answer in ONE span)\n" +
  "WRONG:   <<(mult + 1)>> * n * 7  (part of the answer outside the span — NEVER do this)\n" +
  "Variable names inside << >> must NOT have curly braces: write n not {n}, n1 not {n1}, mult not {mult}.\n" +
  "The LAST << >> span in your response must be the COMPLETE final answer as one arithmetic expression.\n" +
  "Allowed operators inside << >>: +  -  *  /  (  )\n" +
  "Do NOT use ** for exponentiation or // for floor division inside << >>.");

var steps: nat := 0;

// Handle any initial open constrained span: close it within a small budget, then reset.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget : nat := if remaining > 8 then 8 else remaining;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}
// Reset to unconstrained mode regardless of close outcome.
// The while loop never modifies insideConstrainedOut, so this remains vacuously valid.
insideConstrainedOut := false;
currentConstrainedOut := [];

// Main generation: fully unconstrained, letting the LM write << >> spans naturally.
// Constrained-mode was avoided to prevent premature 1-token span closure.
while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
}

cost := steps;

